class Solution {
public:
    vector<int> goodIndices(string s) {
        vector<int> res;
        for (int i = 0; i < (int)s.size(); i++) {
            string t = to_string(i);
            for (int j = i; j > i - (int)t.size() && j >= 0; j--)
                if (s.substr(j, i - j + 1) == t) { res.push_back(i); break; }
        }
        return res;
    }
};

